const cropMode=()=>current()?.group==='crops';
const cropIndex=new Map((DATA.cropPilot||[]).map(x=>[[x.municipio_id,x.cultivo_codigo,x.campana,x.riego,x.definicion_superficie].join('|'),x]));
const cropWords={es:{verano2012_2013:'Verano 2012–2013',invierno2012:'Invierno 2012',todos:'Todos',con_riego:'Con riego',sin_riego:'Sin dato de riego',sin_dato:'Sin dato de riego',otro_especial:'Otros códigos / especiales',riego_produccion:'Para riego y producción',uso_suelo:'Para uso del suelo',sembrada:'Superficie sembrada'},en:{verano2012_2013:'Summer 2012–2013',invierno2012:'Winter 2012',todos:'All',con_riego:'With irrigation',sin_riego:'Without irrigation',sin_dato:'Irrigation not reported',otro_especial:'Other / special codes',riego_produccion:'For irrigation and production',uso_suelo:'For land use',sembrada:'Sown area'}};
cropWords.es.sin_riego='Sin riego';
const cropMeta = () => DATA.cropCatalog.find(x => x.code === current()?.crop_code);
const productFields = ['municipio_id','cultivo_codigo','campana','riego','definicion_superficie','registros','upa_con_registros','upa_superficie_positiva','registros_validos','registros_missing','registros_no_aplica','registros_cero','superficie_ha','estado'];
const productLoads = new Map();
window.receiveCrop = (code, rows) => {
  for (const values of rows) {
    const r = Object.fromEntries(productFields.map((key,i) => [key,values[i]]));
    const key = [r.municipio_id,r.cultivo_codigo,r.campana,r.riego,r.definicion_superficie].join('|');
    if (!cropIndex.has(key)) cropIndex.set(key,r); // Preserve the previous six-product delivery exactly.
  }
};
async function ensureCrop() {
  if (!cropMode()) return;
  const code=current().crop_code;
  if (!productLoads.has(code)) productLoads.set(code,new Promise((resolve,reject) => {
    const script=document.createElement('script');script.src='assets/products/'+code+'.js';
    script.onload=resolve;script.onerror=()=>reject(new Error('No se pudo abrir el archivo local del producto '+code));document.head.append(script);
  }));
  await productLoads.get(code);
}
