function measureLabel(){if(fullMode()&&current().full_quality_blocked)return lang==="es"?"Escala no validada":"Unvalidated scale";if(fullMode())return (current().full_operation==="sum"?(current().full_annual?(lang==="es"?"Producción anual · ":"Annual production · "):current().full_mass_factor?(lang==="es"?"Suma convertida · ":"Converted sum · "):(lang==="es"?"Suma cruda · ":"Raw sum · ")):(lang==="es"?"Conteo · ":"Count · "))+current()["unit_"+lang];return cropMode()?cropMetrics[lang][$('#cropMetric').value]:$('#measure').value==='count'?(current().group==='animals'?words[lang].count:(lang==='es'?'Valor publicado · ':'Published value · ')+current()['unit_'+lang]):words[lang][$('#measure').value]}
function value(r){if(fullMode())return fullValue(r);if(cropMode())return cropRecord(r)?.[$('#cropMetric').value]??null;const a=r[$('#animal').value],m=$('#measure').value;return m==='count'?a:m==='upa'?(r.nroupa>0?a/r.nroupa:null):(r.population_estimated_2013>0?1000*a/r.population_estimated_2013:null)}
