// Counts describe selectable indicators in the current view, not independent fields.
function topicInventory(key){
 const vars=DATA.variables.filter(v=>v.group===key),role=$('#fullRole').value||'primary';
 if(key.startsWith('full_'))return {count:vars.filter(v=>fullIncluded(v,role)).length,kind:'variables'};
 if(key==='crops')return {count:new Set(vars.map(v=>v.crop_code)).size,kind:'codes'};
 if(key==='animals')return {count:vars.length,kind:'groups'};
 if(key==='animals_detail')return {count:vars.length,kind:'categories'};
 return {count:vars.length,kind:'variables'};
}
function updateTopicCounts(){
 const units={es:{variables:['variable','variables'],codes:['código','códigos'],groups:['grupo','grupos'],categories:['categoría','categorías']},en:{variables:['variable','variables'],codes:['code','codes'],groups:['group','groups'],categories:['category','categories']}};
 for(const option of $('#topic').options){
  const key=option.value,info=topicInventory(key),base=TOPICS[lang][key].replace(/\s*·\s*[\d,.]+\s+(?:variables?|codes?|códigos?|groups?|grupos?|categories|category|categorías?)\s*$/i,'');
  option.textContent=base+' · '+info.count.toLocaleString('en-US')+' '+units[lang][info.kind][info.count===1?0:1];
  option.dataset.count=String(info.count);option.dataset.countKind=info.kind;
 }
 $('#topic').title=lang==='es'?'Cantidad de opciones del tema. Los módulos ampliados siguen la vista elegida; categorías y variables no son todas independientes.':'Number of topic options. Expanded modules follow the selected view; categories and variables are not all independent.';
}
